/**
 * Every value Atlas displays travels with a Provenance record. The UI renders
 * it next to the value, so a reader always knows where a number came from,
 * when it was observed, and whether it is synthetic, delayed or end-of-day.
 */
export type Timeliness =
  /** Exchange real-time. Only used when a licensed real-time feed says so. */
  | 'realtime'
  /** Intraday but delayed (e.g. 15 minutes). */
  | 'delayed'
  /** End-of-day / last close. */
  | 'eod'
  /** Periodic releases: filings, macro series, reference data. */
  | 'periodic'
  /** Generated by demo mode. Never mixed with real data. */
  | 'synthetic';

export interface Provenance {
  /** Provider id, e.g. "sec-edgar", "fred", "demo". */
  provider: string;
  /** Human label, e.g. "SEC EDGAR". */
  providerName: string;
  /** When the observation applies (ISO 8601). For a close, the session date. */
  asOf: string | null;
  /** When Atlas retrieved it from the provider (ISO 8601). */
  fetchedAt: string;
  timeliness: Timeliness;
  /** Stated delay in minutes when timeliness is "delayed". */
  delayMinutes?: number;
  currency?: string;
  unit?: string;
  sourceUrl?: string;
  /** Attribution text the provider's terms require. */
  attribution?: string;
  /** True when served from Atlas's cache rather than a fresh call. */
  cached?: boolean;
}

/** A value with its provenance. */
export interface Sourced<T> {
  data: T;
  provenance: Provenance;
}

/**
 * Result of a provider call. "unavailable" is a first-class outcome: callers
 * must render it as unavailable, never as zero or as a fallback number.
 */
export type ProviderResult<T> =
  | ({ status: 'ok' } & Sourced<T>)
  | { status: 'unavailable'; reason: string; provider: string; retryable: boolean };

export function isStale(p: Provenance, now: Date, maxAgeMs: number): boolean {
  if (!p.asOf) return true;
  return now.getTime() - new Date(p.asOf).getTime() > maxAgeMs;
}
